// a small box and its lid
const base = box(60, 40, 20)
hollow(base, { wall: 2, open: 'top' })
const lid = box(60, 40, 3)
hole(lid, { across: 4 })

// a plate with a round peg standing on it
const plate = box(60, 40, 5)
const peg = cylinder(10, 20)
const part = union(plate, peg)

// an L bracket 30 wide, with a boss for a bolt
const sk = sketch('top')
sk.polygon([[0, 0], [60, 0], [60, 10], [10, 10], [10, 40], [0, 40]])
const part = extrude(sk, 30)
const boss = cylinder(16, 8)
const both = union(part, boss)
hole(both, { across: 6 })

// a cup pulled from a sketch, two sloped sides so it comes out of a mould
const sk = sketch('top')
sk.rect(60, 40)
const cup = extrude(sk, 25)
draft(cup.face('right'), 5, { from: 'bottom' })
draft(cup.face('left'), 5, { from: 'bottom' })
hollow(cup, { wall: 2, open: 'top' })

const sk = sketch('top')
sk.rect(60, 40)
const cup = extrude(sk, 25)
draft(cup.face('right'), 5, { from: 'top' })
draft(cup.face('left'), 5, { from: 'top' })

// a plate drawn roughly and dimensioned
const sk = sketch('top')
const r = sk.rectangle([0.3, 0.4], [49, 31])
sk.at(r.bottom.a, [0, 0])
sk.length(r.bottom, 50)
const plate = extrude(sk, 6)
const spacer = cylinder(12, 6)
hole(spacer, { across: 5 })

// an open box with two posts inside for a circuit board
const b = box(80, 50, 20)
hollow(b, { wall: 2, open: 'top' })
const post1 = cylinder(8, 10, { at: [-25, 0, -3] })
const post2 = cylinder(8, 10, { at: [25, 0, -3] })
const body = union(b, post1, post2)
hole(body, { across: 3, at: [-25, 0], deep: 8 })
hole(body, { across: 3, at: [25, 0], deep: 8 })

// cut a round hole with a cylinder as the tool
const b = box(40, 40, 20)
const tool = cylinder(10, 30)
subtract(b, tool)

// a drilled block, three in a row
const b = box(30, 20, 10)
hole(b, { across: 6 })
const row = linearPattern(b, { count: 3, step: [40, 0, 0] })
hole(row, { across: 3, at: [10, 0] })

// a knob spun from a profile, on a square base
const sk = sketch('front', 0)
sk.polygon([[0, 0], [12, 0], [12, 6], [6, 14], [0, 14]])
const knob = revolve(sk, 360)
const base = box(30, 30, 4)
const part = union(knob, base)

