hole(lid, { across: 4, at: [25, 15], counterbore: { across: 8, deep: 1.5 } })

const lid = box(60, 40, 3, { at: [0, 0, 11.5] })
hole(lid, { across: 4, at: [25, 15], counterbore: { across: 8, deep: 1.5 } })
const base = box(60, 40, 20, { at: [0, 0, 0] })
hollow(base, { wall: 2, open: 'top' })

const plate = box(60, 40, 5)
const peg = cylinder(10, 20, { at: [0, 0, 12.5] })
const part = union(plate, peg)

